import { useEffect, useMemo, useState } from "react";
import { useNavigate, useSearchParams } from "react-router-dom";
import { useAuth } from "../context/AuthContext";
import membersData from "../data/members.json";
import { useAvatarByName } from "../context/MembersContext";
import { useLivePlans, CSV_SHARED_CACHE_KEY, CSV_CACHE_TTL } from "../context/LivePlansContext";
import Navbar from "../components/Navbar";
import {
  StatsView,
  TodosView,
  computeMember,
  computeFocusing,
} from "./PlansPage";
import "./PlansPage.css";
import "./MyPage.css";

const CSV_URL =
  "https://docs.google.com/spreadsheets/d/1yAeYVbqyFwePzjjdU0ile_OAmZ-cR8iwu_95KPVsx7o/export?format=csv&gid=0";

const CURRENT_MONTH = new Date().getMonth() + 1;
const LINE_LABELS = Array.from({ length: CURRENT_MONTH }, (_, i) => `${i + 1}월`);

function parseCSVLine(line) {
  const result = [];
  let cur = "";
  let inQ = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (ch === '"') {
      if (inQ && line[i + 1] === '"') { cur += '"'; i++; }
      else { inQ = !inQ; }
    } else if (ch === "," && !inQ) {
      result.push(cur.trim());
      cur = "";
    } else {
      cur += ch;
    }
  }
  result.push(cur.trim());
  return result;
}

function parseCSV(text) {
  const lines = text.replace(/\r/g, "").split("\n").filter((l) => l.trim());
  if (lines.length < 2) return [];
  const headers = parseCSVLine(lines[0]);
  return lines.slice(1).map((line) => {
    const vals = parseCSVLine(line);
    const obj = {};
    headers.forEach((h, i) => { obj[h] = vals[i] ?? ""; });
    return obj;
  });
}

function deduplicateRows(rows) {
  const map = new Map();
  rows.forEach((row) => {
    const key = `${row["이름"]}||${row["계획번호"]}`;
    const prevId = Number(map.get(key)?.["ID"] ?? -1);
    const curId  = Number(row["ID"] ?? 0);
    if (curId > prevId) map.set(key, row);
  });
  return Array.from(map.values());
}

export default function MyPage() {
  const { currentUser, memberId, loading: authLoading } = useAuth();
  const navigate = useNavigate();
  const [searchParams, setSearchParams] = useSearchParams();

  const myMember = useMemo(() => {
    if (memberId == null) return null;
    return membersData.find((m) => String(m.id) === String(memberId)) ?? null;
  }, [memberId]);

  const memberName = myMember?.name ?? null;
  const avatarSrc = useAvatarByName(memberName);
  const livePlans = useLivePlans();

  const [tab, setTab] = useState(() => searchParams.get("tab") === "plans" ? "plans" : "stats");
  const [csvRows, setCsvRows] = useState([]);
  const [csvLoading, setCsvLoading] = useState(true);

  useEffect(() => {
    if (!authLoading && !currentUser) navigate("/", { replace: true });
  }, [authLoading, currentUser, navigate]);

  useEffect(() => {
    // PlansPage와 동일한 공유 캐시 사용
    try {
      const cached = JSON.parse(localStorage.getItem(CSV_SHARED_CACHE_KEY) ?? "null");
      if (cached && Date.now() - cached.ts < CSV_CACHE_TTL && cached.rawText) {
        setCsvRows(deduplicateRows(parseCSV(cached.rawText)));
        setCsvLoading(false);
        return;
      }
    } catch {}
    fetch(CSV_URL)
      .then((r) => r.text())
      .then((text) => {
        const rows = deduplicateRows(parseCSV(text));
        setCsvRows(rows);
        try {
          localStorage.setItem(CSV_SHARED_CACHE_KEY, JSON.stringify({ ts: Date.now(), rawText: text }));
        } catch {}
      })
      .catch(() => {})
      .finally(() => setCsvLoading(false));
  }, []);

  const fsRows = livePlans.map((data) => {
    const createdAt   = data.createdAt?.toDate?.();
    const completedAt = data.completedAt?.toDate?.();
    const fmt = (dt) =>
      dt ? `${dt.getFullYear()}.${String(dt.getMonth()+1).padStart(2,"0")}.${String(dt.getDate()).padStart(2,"0")}` : "";
    return {
      "이름": data.authorName ?? "",
      "계획번호": data.planNumber != null ? String(data.planNumber) : "",
      "계획내용": data.content ?? "",
      "생성일": fmt(createdAt),
      "완료일": fmt(completedAt),
      "상태": data.status === "done" ? "완료" : "미완료",
      "_fsId": data.id,
    };
  });

  const allRows = useMemo(
    () => (fsRows.length === 0 ? csvRows : [...csvRows, ...fsRows]),
    [csvRows, fsRows]
  );


  const computed = useMemo(
    () => (memberName && allRows.length > 0 ? computeMember(allRows, memberName) : null),
    [allRows, memberName]
  );

  const stats = useMemo(() => {
    if (!computed || !memberName) return null;
    return {
      progressPercent: computed.progressPercent,
      lineLabels:      LINE_LABELS,
      plansSeries:     computed.plansSeries,
      finishedSeries:  computed.finishedSeries,
      focusing:        computeFocusing(allRows, memberName),
    };
  }, [computed, memberName, allRows]);

  if (authLoading || !currentUser) return null;


  return (
    <div className="myPageRoot">
      <Navbar />

      <main className="myPageContent">
        {/* 프로필 헤더 */}
        <div className="myPageHeader">
          {avatarSrc && (
            <img src={avatarSrc} alt={myMember?.name ?? "프로필"} className="myPageAvatar" />
          )}
          <div className="myPageInfo">
            <div className="myPageName">{myMember?.name ?? currentUser.email}</div>
            <div className="myPageRole">{myMember?.role ?? "멤버"}</div>
          </div>
        </div>

        {/* 탭 */}
        <div className="myPageTabRow">
          <button
            className={`myPageTabBtn${tab === "stats" ? " active" : ""}`}
            onClick={() => { setTab("stats"); setSearchParams({}); }}
          >Statistics</button>
          <button
            className={`myPageTabBtn${tab === "plans" ? " active" : ""}`}
            onClick={() => { setTab("plans"); setSearchParams({ tab: "plans" }); }}
          >Detailed Plans</button>
        </div>

        {/* 본문 */}
        {!myMember ? (
          <div className="myPageNoProfile">
            Plans 페이지에서 본인 카드를 클릭해 프로필을 연결해주세요.
          </div>
        ) : csvLoading ? (
          <div className="csvStatusMsg">데이터 불러오는 중…</div>
        ) : tab === "stats" ? (
          <StatsView stats={stats} golden={false} />
        ) : (
          <TodosView
            todos={computed?.todos ?? []}
            dones={computed?.dones  ?? []}
            currentUser={currentUser}
            memberName={memberName}
            isOwn={true}
          />
        )}
      </main>
    </div>
  );
}
