import { useEffect, useRef, useState, useCallback, useMemo } from "react";
import { createPortal } from "react-dom";
import { useNavigate } from "react-router-dom";
import { collection, addDoc, serverTimestamp } from "firebase/firestore";
import { db } from "../firebase";
import { nameToAvatarKey, avatarMap, defaultAvatar } from "../utils/avatarMap";
import { useAvatarByName, useMembersMap } from "../context/MembersContext";
import { useLivePlans, useRefreshPlans, useLoadMorePlans, usePlanMutations } from "../context/LivePlansContext";
import { useAuth } from "../context/AuthContext";
import membersData from "../data/members.json";
import "./LiveChatPanel.css";

function MiniProfileCard({ name, onClose }) {
  const membersMap = useMembersMap();
  const member = membersMap[name] ?? membersData.find((m) => m.name === name);
  const avatar = member?.avatarUrl || (member?.avatar && avatarMap[member.avatar]) || defaultAvatar;
  const links = member?.links || {};

  useEffect(() => {
    const handler = (e) => { if (e.key === "Escape") onClose(); };
    document.addEventListener("keydown", handler);
    return () => document.removeEventListener("keydown", handler);
  }, [onClose]);

  if (!member) return null;

  return createPortal(
    <div className="lcpMiniOverlay" onClick={onClose}>
      <div className="lcpMiniCard" onClick={(e) => e.stopPropagation()}>
        <button className="lcpMiniClose" onClick={onClose}>✕</button>
        <div className="lcpMiniTop">
          <img src={avatar} alt={member.name} className="lcpMiniAvatar" />
          <div>
            <div className="lcpMiniName">{member.name}</div>
            <div className="lcpMiniRole">{member.role}</div>
          </div>
        </div>
        {member.quote && <p className="lcpMiniQuote">"{member.quote}"</p>}
        {Array.isArray(member.bullets) && member.bullets.length > 0 && (
          <ul className="lcpMiniBullets">
            {member.bullets.map((b, i) => <li key={i}>{b}</li>)}
          </ul>
        )}
        {Array.isArray(member.goals) && member.goals.length > 0 && (
          <div className="lcpMiniGoals">
            <div className="lcpMiniGoalsLabel">목표</div>
            <ul className="lcpMiniBullets">
              {member.goals.map((g, i) => <li key={i}>{g}</li>)}
            </ul>
          </div>
        )}
        <div className="lcpMiniLinks">
          {links.linkedin?.trim() && (
            <a href={links.linkedin} target="_blank" rel="noreferrer" className="lcpMiniLink">LinkedIn</a>
          )}
        </div>
      </div>
    </div>,
    document.body
  );
}

function buildTimeline(plans) {
  const events = [];
  plans.forEach((plan) => {
    if (plan.createdAt) {
      events.push({ type: "plan", plan, ts: plan.createdAt, id: `plan-${plan.id}` });
    }
    if (plan.editedAt) {
      events.push({ type: "edit", plan, ts: plan.editedAt, id: `edit-${plan.id}` });
    }
    if (plan.status === "done" && plan.completedAt) {
      events.push({ type: "done", plan, ts: plan.completedAt, id: `done-${plan.id}` });
    }
  });
  return events.sort((a, b) => (a.ts?.seconds ?? 0) - (b.ts?.seconds ?? 0));
}

function ChatBubble({ ev, currentUid, onReplyClick, onProfileClick }) {
  const { type, plan } = ev;
  const avatar = useAvatarByName(plan.authorName);

  const bubbleContent = () => {
    if (type === "plan") {
      return (
        <span className="lcpPlanText">
          <span className="lcpNum">{plan.planNumber}번째 계획</span>
          <span className="lcpColon"> : </span>
          <span className="lcpContent">{plan.content}</span>
        </span>
      );
    }
    if (type === "edit") {
      return (
        <div className="lcpBubbleDoneInner">
          <button
            className="lcpReplyQuote lcpReplyQuoteEdit"
            onClick={() => onReplyClick(`plan-${plan.id}`)}
          >
            <span className="lcpReplyNum">{plan.planNumber}번째 계획</span>
            <span className="lcpReplyContent"> : {plan.previousContent ?? plan.content}</span>
          </button>
          <div className="lcpReplyText lcpEditText">✏️ {plan.planNumber}번째 계획 수정: {plan.content}</div>
        </div>
      );
    }
    if (type === "done") {
      return (
        <div className="lcpDoneRow">
          <button
            className="lcpReplyQuote"
            onClick={() => onReplyClick(`plan-${plan.id}`)}
          >
            <span className="lcpReplyNum">{plan.planNumber}번째 계획</span>
            <span className="lcpReplyContent"> : {plan.content}</span>
          </button>
          <span className="lcpDoneBadge">✓</span>
        </div>
      );
    }
    return null;
  };

  const bubbleClass = type === "done" ? " lcpBubbleDone" : type === "edit" ? " lcpBubbleEdit" : "";

  return (
    <div className="lcpRow">
      <img
        src={avatar}
        alt={plan.authorName}
        className="lcpAvatar lcpAvatarClickable"
        onClick={() => onProfileClick(plan.authorName)}
        title={`${plan.authorName} 프로필 보기`}
      />
      <div className="lcpBubbleWrap">
        <div
          className="lcpName lcpNameClickable"
          onClick={() => onProfileClick(plan.authorName)}
        >
          {plan.authorName}
        </div>
        <div className="lcpBubbleRow">
          <div className={`lcpBubble${bubbleClass}`}>
            {bubbleContent()}
          </div>
        </div>
      </div>
    </div>
  );
}

export default function LiveChatPanel() {
  const { currentUser, memberId } = useAuth();
  const navigate = useNavigate();
  const plans = useLivePlans();
  const { appendPlan } = usePlanMutations();
  const { loadMore, hasMore } = useLoadMorePlans();
  const loadingMore = useRef(false);
  const [open, setOpen] = useState(false);
  const [input, setInput] = useState("");
  const [sending, setSending] = useState(false);
  const [panelWidth, setPanelWidth] = useState(300);
  const [searchQuery, setSearchQuery] = useState("");
  const [showSearch, setShowSearch] = useState(false);
  const [atBottom, setAtBottom] = useState(true);
  const [profileName, setProfileName] = useState(null);
  const panelRef = useRef(null);
  const feedRef = useRef(null);
  const bottomRef = useRef(null);
  const bubbleRefs = useRef({});
  const inputRef = useRef(null);
  const searchRef = useRef(null);
  const isResizing = useRef(false);
  const resizeStartX = useRef(0);
  const resizeStartW = useRef(0);

  const startResize = useCallback((e) => {
    isResizing.current = true;
    resizeStartX.current = e.clientX;
    resizeStartW.current = panelWidth;
    document.body.style.userSelect = "none";
    const onMove = (ev) => {
      if (!isResizing.current) return;
      const delta = resizeStartX.current - ev.clientX;
      const next = Math.max(240, Math.min(600, resizeStartW.current + delta));
      setPanelWidth(next);
      document.documentElement.style.setProperty("--lcp-width", `${next}px`);
    };
    const onUp = () => {
      isResizing.current = false;
      document.body.style.userSelect = "";
      window.removeEventListener("mousemove", onMove);
      window.removeEventListener("mouseup", onUp);
    };
    window.addEventListener("mousemove", onMove);
    window.addEventListener("mouseup", onUp);
  }, [panelWidth]);

  const myName = memberId != null
    ? (membersData.find((m) => String(m.id) === String(memberId))?.name ?? null)
    : null;
  const myAvatarKey = myName ? (nameToAvatarKey[myName] || "image15.png") : null;

  const openRef = useRef(open);
  useEffect(() => { openRef.current = open; }, [open]);

useEffect(() => {
    document.documentElement.style.setProperty("--lcp-width", `${panelWidth}px`);
  }, [panelWidth]);

  useEffect(() => {
    if (open) {
      document.body.classList.add("lcp-open");
      setTimeout(() => {
        if (feedRef.current) feedRef.current.scrollTop = feedRef.current.scrollHeight;
      }, 300);
    } else {
      document.body.classList.remove("lcp-open");
      setShowSearch(false);
      setSearchQuery("");
    }
    return () => document.body.classList.remove("lcp-open");
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open]);

  useEffect(() => {
    if (open && atBottom && feedRef.current) {
      feedRef.current.scrollTop = feedRef.current.scrollHeight;
    }
  }, [plans, open, atBottom]);

  // 스크롤 위치 감지
  const handleScroll = useCallback(() => {
    const el = feedRef.current;
    if (!el) return;
    const near = el.scrollHeight - el.scrollTop - el.clientHeight < 80;
    setAtBottom(near);
    if (el.scrollTop < 80 && hasMore && !loadingMore.current) {
      const prevHeight = el.scrollHeight;
      loadingMore.current = true;
      loadMore().then(() => {
        requestAnimationFrame(() => {
          el.scrollTop = el.scrollHeight - prevHeight;
          loadingMore.current = false;
        });
      });
    }
  }, [hasMore, loadMore]);

  useEffect(() => {
    const el = feedRef.current;
    if (!el) return;
    el.addEventListener("scroll", handleScroll);
    return () => el.removeEventListener("scroll", handleScroll);
  }, [handleScroll, open]);

  // 검색 토글 시 input 포커스
  useEffect(() => {
    if (showSearch) setTimeout(() => searchRef.current?.focus(), 50);
  }, [showSearch]);

  const getNextPlanNumber = useCallback(() => {
    if (!currentUser) return 1;
    const myPlans = plans.filter((p) => p.authorUid === currentUser.uid);
    const stateMax = myPlans.reduce((max, p) => Math.max(max, p.planNumber ?? 0), 0);
    const raw = parseInt(localStorage.getItem("lcpMaxPlan") ?? "0", 10);
    const localMax = Number.isFinite(raw) ? raw : 0;
    return Math.max(stateMax, localMax) + 1;
  }, [currentUser, plans]);

  const handleSend = async () => {
    const content = input.trim();
    if (!content || sending || !currentUser || !myName) return;
    setSending(true);
    try {
      const planNumber = getNextPlanNumber();
      const docRef = await addDoc(collection(db, "livePlans"), {
        planNumber,
        content,
        authorName: myName,
        authorUid: currentUser.uid,
        avatarKey: myAvatarKey || "image15.png",
        status: "active",
        createdAt: serverTimestamp(),
        completedAt: null,
      });
      setInput("");
      setAtBottom(true);
      appendPlan({ id: docRef.id, planNumber, content, authorName: myName, authorUid: currentUser.uid, avatarKey: myAvatarKey || "image15.png", status: "active" });
    } finally {
      setSending(false);
      setTimeout(() => inputRef.current?.focus(), 0);
    }
  };

  const handleReplyClick = (targetId) => {
    const el = bubbleRefs.current[targetId];
    if (el && feedRef.current) {
      el.scrollIntoView({ behavior: "smooth", block: "center" });
      el.classList.add("lcpHighlight");
      setTimeout(() => el.classList.remove("lcpHighlight"), 1500);
    }
  };

  const handleProfileClick = useCallback((authorName) => {
    setProfileName(authorName);
  }, []);

  const scrollToBottom = () => {
    if (feedRef.current) {
      feedRef.current.scrollTop = feedRef.current.scrollHeight;
      setAtBottom(true);
    }
  };

  const timeline = buildTimeline(plans);

  const filteredTimeline = useMemo(() => {
    if (!searchQuery.trim()) return timeline;
    const q = searchQuery.toLowerCase();
    return timeline.filter((ev) =>
      ev.plan.content?.toLowerCase().includes(q) ||
      ev.plan.authorName?.toLowerCase().includes(q) ||
      String(ev.plan.planNumber).includes(q)
    );
  }, [timeline, searchQuery]);

  return (
    <>
      {profileName && (
        <MiniProfileCard name={profileName} onClose={() => setProfileName(null)} />
      )}
      <div
        ref={panelRef}
        className={`lcpPanel${open ? " lcpPanelOpen" : ""}`}
        style={{ width: `${panelWidth}px` }}
      >
        <div className="lcpResizeHandle" onMouseDown={startResize} />
        <div className="lcpHeader">
          <span className="lcpHeaderTitle">💬 Live Plans</span>
          <div className="lcpHeaderActions">
            <button
              className={`lcpSearchToggle${showSearch ? " active" : ""}`}
              onClick={() => setShowSearch((v) => !v)}
              title="검색"
            >🔍</button>
            <button className="lcpCloseBtn" onClick={() => setOpen(false)}>✕</button>
          </div>
        </div>

        {showSearch && (
          <div className="lcpSearchBar">
            <input
              ref={searchRef}
              className="lcpSearchInput"
              placeholder="이름, 계획 내용 검색…"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
            />
            {searchQuery && (
              <button className="lcpSearchClear" onClick={() => setSearchQuery("")}>✕</button>
            )}
          </div>
        )}

        <div className="lcpFeed" ref={feedRef}>
          {filteredTimeline.length === 0 ? (
            <div className="lcpEmpty">
              {searchQuery ? "검색 결과가 없어요." : "아직 등록된 계획이 없어요."}
            </div>
          ) : (
            filteredTimeline.map((ev) => (
              <div
                key={ev.id}
                ref={(el) => { if (el) bubbleRefs.current[ev.id] = el; }}
              >
                <ChatBubble
                  ev={ev}
                  currentUid={currentUser?.uid ?? null}
                  onReplyClick={handleReplyClick}
                  onProfileClick={handleProfileClick}
                />
              </div>
            ))
          )}
          <div ref={bottomRef} />
        </div>

        {!atBottom && (
          <button className="lcpScrollBottom" onClick={scrollToBottom} title="맨 아래로">
            ↓
          </button>
        )}

        {currentUser && myName && (
          <div className="lcpInputRow">
            <input
              ref={inputRef}
              className="lcpInput"
              placeholder="계획을 입력하세요…"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => e.key === "Enter" && !e.shiftKey && handleSend()}
              disabled={sending}
            />
            <button
              className="lcpSendBtn"
              onClick={handleSend}
              disabled={sending || !input.trim()}
            >
              {sending ? "…" : "↑"}
            </button>
          </div>
        )}
      </div>
      {!open && currentUser && (
        <button className="lcpFab" onClick={() => setOpen(true)} aria-label="Live Plans 채팅 열기">
          <span className="lcpFabIcon">💬</span>
          <span>Live</span>
        </button>
      )}
    </>
  );
}
