import { createContext, useCallback, useContext, useEffect, useRef, useState } from "react";
import {
  collection, onSnapshot, query, where, orderBy, Timestamp,
  addDoc, updateDoc, doc, serverTimestamp,
} from "firebase/firestore";
import { db } from "../firebase";
import { useAuth } from "./AuthContext";

const LivePlansContext = createContext([]);
const LivePlansApiContext = createContext({});

const CSV_URL = "https://docs.google.com/spreadsheets/d/1yAeYVbqyFwePzjjdU0ile_OAmZ-cR8iwu_95KPVsx7o/export?format=csv&gid=0";
export const CSV_SHARED_CACHE_KEY = `sharedCSV_${CSV_URL.slice(-12)}`;
export const CSV_CACHE_TTL = 60 * 60 * 1000; // 1시간

/* CSV 한 줄 파서 (따옴표 처리) */
function parseCSVLine(line) {
  const result = [];
  let cur = "", inQ = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (ch === '"') {
      if (inQ && line[i + 1] === '"') { cur += '"'; i++; }
      else inQ = !inQ;
    } else if (ch === ',' && !inQ) {
      result.push(cur); cur = "";
    } else {
      cur += ch;
    }
  }
  result.push(cur);
  return result;
}

/* CSV 날짜 "YYYY.MM.DD" 또는 "YYYY.MM.DD HH:mm" → Date (KST) */
function parseCSVDate(s) {
  if (!s) return null;
  const [datePart, timePart] = s.trim().split(" ");
  const parts = datePart.split(".");
  if (parts.length < 3) return null;
  const [h, m] = timePart ? timePart.split(":").map(Number) : [0, 0];
  // KST 기준으로 파싱 (UTC+9 보정)
  const utc = Date.UTC(Number(parts[0]), Number(parts[1]) - 1, Number(parts[2]), h - 9, m);
  return new Date(utc);
}

/* CSV rows → plan 객체 배열 */
function csvToPlans(text) {
  const lines = text.replace(/\r/g, "").split("\n").filter((l) => l.trim());
  if (lines.length < 2) return [];
  const headers = parseCSVLine(lines[0]);
  const idxOf = (name) => headers.indexOf(name);

  return lines.slice(1).map((line, i) => {
    const cols = parseCSVLine(line);
    const get = (name) => cols[idxOf(name)] ?? "";
    const createdDate = parseCSVDate(get("생성일"));
    const completedDate = parseCSVDate(get("완료일"));
    return {
      id: `csv-${get("ID") || i}`,
      _fromCSV: true,
      authorName: get("이름"),
      planNumber: Number(get("계획번호")) || 0,
      content: get("계획내용"),
      status: get("상태") === "완료" ? "done" : "active",
      createdAt: createdDate ? Timestamp.fromDate(createdDate) : null,
      completedAt: completedDate ? Timestamp.fromDate(completedDate) : null,
    };
  }).filter((p) => p.authorName && p.planNumber);
}

export function LivePlansProvider({ children }) {
  const { currentUser } = useAuth();
  const [csvPlans, setCsvPlans] = useState([]);
  const [livePlans, setLivePlans] = useState([]);
  const [csvCutoff, setCsvCutoff] = useState(null); // CSV 마지막 계획 시각

  /* ── 1. CSV 로드 (앱 시작 시 1회, 1시간 캐시) ── */
  useEffect(() => {
    const cached = (() => {
      try {
        const raw = localStorage.getItem(CSV_SHARED_CACHE_KEY);
        if (!raw) return null;
        const parsed = JSON.parse(raw);
        if (Date.now() - parsed.ts > CSV_CACHE_TTL) return null;
        // data(파싱된 plans) 또는 rawText 중 하나라도 있으면 사용
        if (parsed.data && parsed.cutoff) return { data: parsed.data, cutoff: parsed.cutoff };
        if (parsed.rawText) {
          const plans = csvToPlans(parsed.rawText);
          const maxTs = plans.reduce((max, p) => Math.max(max, p.createdAt?.seconds ?? 0), 0);
          return { data: plans, cutoff: new Date(maxTs * 1000).toISOString() };
        }
        return null;
      } catch { return null; }
    })();

    if (cached) {
      setCsvPlans(cached.data ?? []);
      setCsvCutoff(cached.cutoff ? new Date(cached.cutoff) : new Date(0));
      return;
    }

    fetch(CSV_URL)
      .then((r) => r.text())
      .then((text) => {
        const plans = csvToPlans(text);
        const maxTs = plans.reduce((max, p) => {
          const s = p.createdAt?.seconds ?? 0;
          return s > max ? s : max;
        }, 0);
        const cutoff = new Date(maxTs * 1000);
        setCsvPlans(plans);
        setCsvCutoff(cutoff);
        try {
          // rawText도 함께 저장 → PlansPage가 재사용
          localStorage.setItem(CSV_SHARED_CACHE_KEY, JSON.stringify({
            ts: Date.now(), data: plans, cutoff: cutoff.toISOString(), rawText: text,
          }));
        } catch {}
      })
      .catch(() => setCsvCutoff(new Date(0)));
  }, []);

  /* ── 2. onSnapshot: 신규 계획 + 최근 완료된 계획 ── */
  useEffect(() => {
    if (!currentUser || csvCutoff === null) return;

    const cutoffTs = Timestamp.fromDate(csvCutoff);

    // 새로 생성된 계획만 구독 (completedAt 쿼리 제거 — null 문서 전체 스캔 방지)
    const q1 = query(
      collection(db, "livePlans"),
      where("createdAt", ">", cutoffTs),
      orderBy("createdAt", "asc")
    );

    const unsub1 = onSnapshot(q1, (snap) => {
      const docs = snap.docs.map((d) => ({ id: d.id, ...d.data() }));
      setLivePlans((prev) => {
        const map = new Map(prev.map((p) => [p.id, p]));
        docs.forEach((p) => map.set(p.id, p));
        return Array.from(map.values());
      });
    });

    return () => unsub1();
  }, [currentUser, csvCutoff]);

  /* ── 3. 병합: CSV + 실시간 (중복 제거) ── */
  const plans = (() => {
    const map = new Map();
    const key = (p) => `${String(p.authorName ?? "").trim()}||${Number(p.planNumber) || 0}`;
    // CSV 먼저 — _csvDone 플래그 추가 (완료 탭 기준)
    csvPlans.forEach((p) => map.set(key(p), { ...p, _csvDone: p.status === "done" }));
    // Firebase 오버레이
    livePlans.forEach((p) => {
      const k = key(p);
      const csvVersion = map.get(k);
      if (csvVersion?._csvDone) {
        // CSV가 완료 → CSV가 authority, Firebase로 덮어쓰지 않음
        return;
      }
      if (p.pendingComplete || p.status === "done") {
        // Firebase 완료 예정 또는 완료 상태인데 CSV는 아직 미완료 → 완료 예정
        map.set(k, { ...p, _pendingSync: true });
      } else {
        // Firebase active → CSV active를 덮어씀 (dedup, Firebase 우선)
        map.set(k, p);
      }
    });
    return Array.from(map.values()).sort(
      (a, b) => (a.createdAt?.seconds ?? 0) - (b.createdAt?.seconds ?? 0)
    );
  })();

  /* ── 4. 완료 예정 자동 완료 (1시간 후 status: "done") ── */
  const livePlansRef = useRef(livePlans);
  useEffect(() => { livePlansRef.current = livePlans; }, [livePlans]);

  useEffect(() => {
    if (!currentUser) return;
    const ONE_HOUR_MS = 60 * 60 * 1000;
    const interval = setInterval(async () => {
      const now = Date.now();
      const toComplete = livePlansRef.current.filter(
        (p) => p.pendingComplete && p.pendingAt?.seconds && (now - p.pendingAt.seconds * 1000) > ONE_HOUR_MS
      );
      for (const plan of toComplete) {
        try {
          await updateDoc(doc(db, "livePlans", plan.id), {
            status: "done",
            completedAt: { seconds: Math.floor(now / 1000), nanoseconds: 0 },
            pendingComplete: false,
          });
        } catch {}
      }
    }, 60 * 1000);
    return () => clearInterval(interval);
  }, [currentUser]);

  /* ── 로컬 mutations (쓰기 후 즉시 반영, 읽기 0) ── */
  const appendPlan = useCallback((plan) => {
    setLivePlans((prev) => {
      if (prev.some((p) => p.id === plan.id)) return prev;
      return [...prev, plan];
    });
  }, []);

  const updatePlan = useCallback((id, changes) => {
    setLivePlans((prev) => {
      const exists = prev.some((p) => p.id === id);
      if (exists) return prev.map((p) => p.id === id ? { ...p, ...changes } : p);
      // CSV에만 있는 계획 — livePlans에 추가해서 CSV 버전 덮어씀
      return [...prev, { id, ...changes }];
    });
  }, []);

  const removePlan = useCallback((id) => {
    setLivePlans((prev) => prev.filter((p) => p.id !== id));
  }, []);

  const refreshCSV = useCallback(() => {
    localStorage.removeItem("lcpCSVCache");
    fetch(CSV_URL)
      .then((r) => r.text())
      .then((text) => {
        const plans = csvToPlans(text);
        setCsvPlans(plans);
        try {
          localStorage.setItem("lcpCSVCache", JSON.stringify({ ts: Date.now(), data: plans }));
        } catch {}
      })
      .catch(() => {});
  }, []);

  return (
    <LivePlansApiContext.Provider value={{
      appendPlan, updatePlan, removePlan, refreshCSV,
      // 하위 호환
      refreshPlans: refreshCSV,
      loadMore: () => Promise.resolve(),
      hasMore: false,
    }}>
      <LivePlansContext.Provider value={plans}>
        {children}
      </LivePlansContext.Provider>
    </LivePlansApiContext.Provider>
  );
}

export function useLivePlans() { return useContext(LivePlansContext); }
export function useRefreshPlans() { return useContext(LivePlansApiContext).refreshPlans ?? (() => {}); }
export function useLoadMorePlans() {
  const { loadMore, hasMore } = useContext(LivePlansApiContext);
  return { loadMore: loadMore ?? (() => Promise.resolve()), hasMore: hasMore ?? false };
}
export function usePlanMutations() {
  const { appendPlan, updatePlan, removePlan } = useContext(LivePlansApiContext);
  return {
    appendPlan: appendPlan ?? (() => {}),
    updatePlan: updatePlan ?? (() => {}),
    removePlan: removePlan ?? (() => {}),
  };
}
